    receipts: new NativeReceipts(path.join(directory, "receipts")),
    normalizeImage,
    renderer: async (request) => {
      const id = randomUUID();
      return decodeToolResult(
        await callTool({
          namespace: "codex_app",
          tool: "codex_web_native_v1",
          arguments: request,
          callId: id,
          threadId: contextThreadId,
          turnId: "codex-web-native-adapter",
        }),
