    clients.add(client);
    const timeout = setTimeout(() => socket.destroy(), 5000);
    const frames = setInterval(() => {
      for (const frame of client.frames.values())
        write(client, { event: "native/cu/capture", data: frame }, true);
      client.frames.clear();
