          await host.verify();
          client.authenticated = true;
          clearTimeout(timeout);
          write(client, {
            id: message.id,
            result: {
              ...host.capabilities(),
              desktopVersion: approval.desktopVersion,
              planSha256: approval.planSha256,
              patchedArchiveSha256: actual,
              captureStatuses: [...host.captureStatuses.values()],
