          op: "message/prepare",
          conversationId: params.conversationId,
          prompt: params.prompt,
          attachments,
        });
        if (
          !prepared?.bundle?.message?.id ||
          prepared.conversationId !== params.conversationId
        )
          throw nativeError(
            "Native message preparation returned no message identity",
            true,
          );
